/** Functional interface similar to JUnit 5's Executable, allowing checked exceptions. */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

/** Functional interface for supplier methods that may throw checked exceptions. */
@FunctionalInterface
private interface SupplierWithException<T> {
    T get() throws Exception;
}

/**
 * Asserts that the supplied code does not throw any exception. If an exception is thrown,
 * the test fails with the provided message.
 */
private static <T> T assertDoesNotThrow(SupplierWithException<T> supplier, String message) {
    try {
        return supplier.get();
    } catch (Exception e) {
        fail(message + " – unexpected exception: " + e);
        return null; // Unreachable, but required for compilation.
    }
}

