// Helper method to write an array of long values and return the JSON string without throwing checked exceptions.
private String writeLongs(long... values) {
    try {
        StringWriter stringWriter = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(stringWriter);
        jsonWriter.beginArray();
        for (long v : values) {
            jsonWriter.value(v);
        }
        jsonWriter.endArray();
        jsonWriter.close();
        return stringWriter.toString();
    } catch (IOException e) {
        throw new AssertionError("Unexpected IOException during JSON writing", e);
    }
}

