/** Functional interface allowing a supplier that can throw a checked exception. */
@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

/**
 * Executes the given {@code supplier} and fails the test with the provided {@code message}
 * if any exception is thrown.
 */
private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier, String message) {
    try {
        return supplier.get();
    } catch (Exception e) {
        fail(message + ": " + e);
        return null; // Unreachable, but required for compilation.
    }
}

