public void testSet() {
  JsonArray a = new JsonArray();
  a.add(1);

  List<JsonElement> list = a.asList();
  JsonElement old = list.set(0, new JsonPrimitive(2));
  assertThat(old).isEqualTo(new JsonPrimitive(1));
  assertThat(list.get(0)).isEqualTo(new JsonPrimitive(2));
