/**
 * Test that verifies the child element and child node counts for a mixed‑content table row.
 */
@Test
public void testChildSizeWithMixedContent() {
    Document doc = Jsoup.parse(
        "<table><tbody>\n" +
        "<tr>\n" +
        "<td>15:00</td>\n" +
        "<td>sport</td>\n" +
        "</tr>\n" +
        "</tbody></table>");
    Element row = doc.selectFirst("table tbody tr");
    assertEquals(
        "Expected number of direct child elements (td) in the row to be 2",
        2,
        row.childrenSize());
    assertEquals(
        "Expected total number of child nodes (including text nodes) in the row to be 5",
        5,
        row.childNodeSize());
}

/**
 * Helper method that creates a document with various relative and absolute URLs and returns the list of <a> elements.
 *
 * @return Elements collection containing the <a> tags from the test HTML.
 */
private Elements getRelativeUrlElements() {
    String html = "<body>"
        + "<a href='./one.html'>One</a> "
        + "<a href='two.html'>two</a> "
        + "<a href='../three.html'>Three</a> "
        + "<a href='//example2.com/four/'>Four</a> "
        + "<a href='https://example2.com/five/'>Five</a>"
        + "</body>";
    Document doc = Jsoup.parse(html, "http://example.com/bar/");
    return doc.select("a");
}

