private static final int EXPECTED_FORM_DATA_SIZE = 3;
private static final int USER_INDEX = 0;
private static final int PASS_INDEX = 1;
private static final int LOGIN_INDEX = 2;

@Test
public void adoptedFormsRetainInputs() {
    String html = "<html>\n" +
            "<body>  \n" +
            "  <table>\n" +
            "      <form action=\"/hello.php\" method=\"post\">\n" +
            "      <tr><td>User:</td><td> <input type=\"text\" name=\"user\" /></td></tr>\n" +
            "      <tr><td>Password:</td><td> <input type=\"password\" name=\"pass\" /></td></tr>\n" +
            "      <tr><td><input type=\"submit\" name=\"login\" value=\"login\" /></td></tr>\n" +
            "   </form>\n" +
            "  </table>\n" +
            "</body>\n" +
            "</html>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    assertEquals("Expected number of form fields", EXPECTED_FORM_DATA_SIZE, data.size());
    assertEquals("Key of first form field should be 'user'", "user", data.get(USER_INDEX).key());
    assertEquals("Key of second form field should be 'pass'", "pass", data.get(PASS_INDEX).key());
    assertEquals("Key of third form field should be 'login'", "login", data.get(LOGIN_INDEX).key());
}

