private static final int INITIAL_SEEN = 0;
private static final int EXPECTED_ATTRIBUTE_COUNT = 3;

private Attributes createTestAttributes() {
    Attributes a = new Attributes();
    a.put("Tot", "1");
    a.put("Hello", "2");
    a.put("data-name", "3");
    return a;
}

private void verifyIterationOrder(Attributes a) {
    int seen = INITIAL_SEEN;
    for (Attribute attribute : a) {
        seen++;
        assertEquals(
            "Attribute value should match its iteration order (expected " + seen + ")",
            String.valueOf(seen),
            attribute.getValue()
        );
    }
}

private int countAttributes(Attributes a) {
    int seen = INITIAL_SEEN;
    for (Attribute ignored : a) {
        seen++;
    }
    return seen;
}

@Test
public void testIteratorHasNext_IterationOrder() {
    Attributes a = createTestAttributes();
    verifyIterationOrder(a);
}

@Test
public void testIteratorHasNext_TotalCount() {
    Attributes a = createTestAttributes();
    int actualCount = countAttributes(a);
    assertEquals(
        "Total number of attributes should be " + EXPECTED_ATTRIBUTE_COUNT,
        EXPECTED_ATTRIBUTE_COUNT,
        actualCount
    );
}

