private File copyResourceToTempDir(String resourcePath, File tempDir) throws IOException {
    try (InputStream is = DocumentTest.class.getResourceAsStream(resourcePath)) {
        if (is == null) {
            throw new IllegalArgumentException("Resource not found: " + resourcePath);
        }
        Path destination = new File(tempDir, new File(resourcePath).getName()).toPath();
        Files.copy(is, destination);
        return destination.toFile();
    }
}

