/**
 * Helper that loads a test file, verifies its existence, and parses it with Jsoup.
 *
 * @param resourcePath class‑path resource to load
 * @param charset      character set to use (may be {@code null})
 * @param baseUri      base URI for the document
 * @return the parsed {@link Document}
 */
private Document parseDocument(String resourcePath, String charset, String baseUri) {
    File file = ParseTest.getFile(resourcePath);
    assertTrue("Test file does not exist: " + file.getPath(), file.exists());
    try {
        return Jsoup.parse(file, charset, baseUri);
    } catch (IOException e) {
        fail("Unexpected IOException while parsing " + resourcePath + ": " + e.getMessage());
        return null; // unreachable, required for compilation
    }
}

