        this.doc = doc;
        this.one = one;
        this.two = two;
    }
}

private AbsPrefixElements setupAbsPrefixElements() {
    Document doc = Jsoup.parse("<a id=1 href='/foo'>One</a> <a id=2 href='https://jsoup.org/'>Two</a>");
    Element one = doc.select("#1").first();
    Element two = doc.select("#2").first();
    return new AbsPrefixElements(doc, one, two);
}

@Test
public void testHandlesAbsPrefixOnHasAttr_ElementWithoutAbsUrl() {
    AbsPrefixElements fixture = setupAbsPrefixElements();
    Element one = fixture.one;

    assertFalse("Element #1 should not have an absolute href attribute", one.hasAttr("abs:href"));
    assertTrue("Element #1 should have the href attribute", one.hasAttr("href"));
    assertEquals("Element #1 absolute URL should be empty", "", one.absUrl("href"));
}

@Test
public void testHandlesAbsPrefixOnHasAttr_ElementWithAbsUrl() {
    AbsPrefixElements fixture = setupAbsPrefixElements();
    Element two = fixture.two;

    assertTrue("Element #2 should have an absolute href attribute", two.hasAttr("abs:href"));
    assertTrue("Element #2 should have the href attribute", two.hasAttr("href"));
    assertEquals("Element #2 absolute URL should match the full URL", "https://jsoup.org/", two.absUrl("href"));
}

