private static final String PRE_HTML = "<pre><code><span><b>code\n\ncode</b></span></code></pre>";
private static final String TABLE_HTML = "<table><tbody>\n<tr>\n<td>15:00</td>\n<td>sport</td>\n</tr>\n</tbody></table>";

private Document setupTestKeepsPreTextAtDepth() {
    return Jsoup.parse(PRE_HTML);
}

private Element getTableRow() {
    Document doc = Jsoup.parse(TABLE_HTML);
    return doc.selectFirst("table tbody tr");
}

@Test
public void testKeepsPreTextAtDepth_TextContent() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("Document text should be 'code\\n\\ncode'", "code\n\ncode", doc.text());
}

@Test
public void testKeepsPreTextAtDepth_HtmlPreservation() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("HTML output should preserve the original markup", PRE_HTML, doc.body().html());
}

@Test
public void testChildSizeWithMixedContent_ChildrenSize() {
    Element row = getTableRow();
    assertEquals("Row should have 2 child elements", 2, row.childrenSize());
}

@Test
public void testChildSizeWithMixedContent_ChildNodeSize() {
    Element row = getTableRow();
    assertEquals("Row should have 5 child nodes", 5, row.childNodeSize());
}

